# Generated by `cargo xtask formula` in michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.13.0/acs-0.13.0-aarch64-apple-darwin.tar.gz"
      sha256 "d49717906580eba3e1ad14d12805d33d7e026a4be11d40a787e4f463ea7ea30b"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.13.0/acs-0.13.0-x86_64-apple-darwin.tar.gz"
      sha256 "7d0b776327d3dab16ab0d73cccdcf7d065329f9ea0d1e692eac75b92c185527e"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.13.0/acs-0.13.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "c3d8572dd016ea154490da41beb4adf6fe6b78120a325c71cd668f5e41e05118"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.13.0/acs-0.13.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "4336005c044412d1e940fbf033592d4d325ef6694d96b84b7bfcbab0bfee6d6a"
    end
  end

  def install
    bin.install "acs"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
  end
end
